referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const escape = (s) =>
    s
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  const get = (v, p) => p.reduce((x, k) => (x != null && Object.hasOwn(x, k) ? x[k] : null), v);
  return d.template.replace(/{{{([a-zA-Z0-9_.]+)}}}|{{([a-zA-Z0-9_.]+)}}/g, (_m, raw, escaped) => {
    const v = get(d.data, (raw ?? escaped).split("."));
    const text = v === null ? "" : String(v);
    return raw ? text : escape(text);
  });
}

