type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const escape = (s: string): string =>
    s
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  const get = (v: any, p: string[]): any =>
    p.reduce((x: any, k: string) => (x != null && Object.hasOwn(x, k) ? x[k] : null), v);
  return d.template.replace(
    /{{{([a-zA-Z0-9_.]+)}}}|{{([a-zA-Z0-9_.]+)}}/g,
    (_m: string, raw: string, escaped: string) => {
      const v = get(d.data, (raw ?? escaped).split("."));
      const text = v === null ? "" : String(v);
      return raw ? text : escape(text);
    },
  );
}
